## Safety Layer: CloudWatch Synthetics + Alarms

### API Canary for Critical Path&#xA;&#xA;

```javascript
// checkout-canary.js
const synthetics = require('Synthetics');
const log = require('SyntheticsLogger');

const checkoutTest = async () => {
  // Step 1: Health check
  await synthetics.executeHttpStep('Health Check', {
    hostname: 'api.example.com',
    path: '/health',
    port: 443,
    protocol: 'https:',
    method: 'GET'
  }, async (response) => {
    if (response.statusCode !== 200) {
      throw new Error(`Health check failed: ${response.statusCode}`);
    }
  });

  // Step 2: Test checkout flow with feature flag header
  await synthetics.executeHttpStep('Checkout Flow', {
    hostname: 'api.example.com',
    path: '/v1/checkout',
    port: 443,
    protocol: 'https:',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-user-id': 'synthetic-test-user',
      'x-feature-flags': 'new_checkout_flow'
    },
    body: JSON.stringify({
      items: [{ id: 'sku-123', qty: 1 }],
      payment_method: 'card'
    })
  }, async (response) => {
    if (response.statusCode !== 200) {
      throw new Error(`Checkout failed: ${response.statusCode}`);
    }
    const body = JSON.parse(response.body);
    if (!body.order_id) {
      throw new Error('No order_id in response');
    }
    log.info(`Order created: ${body.order_id}`);
  });

  // Step 3: Latency check
  await synthetics.executeHttpStep('Latency Check', {
    hostname: 'api.example.com',
    path: '/v1/checkout',
    port: 443,
    protocol: 'https:',
    method: 'POST',
    headers: { 'x-user-id': 'synthetic-test-user' }
  }, async (response, requestOptions, stepConfig) => {
    const latency = stepConfig.stepDuration;
    if (latency > 2000) {
      throw new Error(`Checkout too slow: ${latency}ms`);
    }
  });
};

exports.handler = async () => {
  return await checkoutTest();
};
```

